class Config {
  final String jwtSecret;
  final String dbUrl;
  final int port;

  const Config({required this.jwtSecret, required this.dbUrl, required this.port});

  factory Config.fromEnvironment() {
    return Config(
      jwtSecret: Platform.environment['JWT_SECRET'] ??
          (throw StateError('JWT_SECRET is required')),
      dbUrl:     Platform.environment['DATABASE_URL'] ??
          (throw StateError('DATABASE_URL is required')),
      port:      int.parse(Platform.environment['PORT'] ?? '8080'),
    );
  }
}

