// bin/server.dart
import 'dart:io';
import 'package:shelf/shelf_io.dart' as shelf_io;
import 'package:myapp/myapp.dart';

Future<void> main() async {
  final config  = Config.fromEnvironment();
  final app     = Application(config);
  final handler = await app.createHandler();

  final server = await shelf_io.serve(
    handler,
    InternetAddress.anyIPv4,
    config.port,
  );

  print('Server running on http://${server.address.host}:${server.port}');

  ProcessSignal.sigint.watch().listen((_) async {
    await app.close();
    await server.close();
    exit(0);
  });
}

// lib/src/app.dart
class Application {
  final Config config;
  late final UserRepository _userRepository;
  late final UserService _userService;

  Application(this.config);

  Future<Handler> createHandler() async {
    _userRepository = UserRepository(config.dbUrl);
    _userService    = UserService(_userRepository, config);

    final healthHandler = HealthHandler();
    final usersHandler  = UsersHandler(_userService);

    final router = Router()
      ..mount('/health',       healthHandler.router.call)
      ..mount('/api/v1/users', usersHandler.router.call);

    return const Pipeline()
        .addMiddleware(loggingMiddleware())
        .addMiddleware(corsMiddleware())
        .addMiddleware(handleErrors())
        .addHandler(router.call);
  }

  Future<void> close() async {
    await _userRepository.close();
  }
}

// lib/src/handlers/users_handler.dart
class UsersHandler {
  final UserService _userService;
  UsersHandler(this._userService);

  Router get router {
    final r = Router();
    r.post('/register', _register);
    r.post('/login',    _login);
    r.get('/',          _withAuth(_getAll));
    r.get('/&lt;id>',      _withAuth(_getById));
    r.put('/&lt;id>',      _withAuth(_update));
    r.delete('/&lt;id>',   _withAuth(_delete));
    return r;
  }

  Handler _withAuth(Handler handler) =>
      const Pipeline().addMiddleware(authMiddleware()).addHandler(handler);

  Future<Response> _register(Request request) async {
    final body = jsonDecode(await request.readAsString()) as Map<String, dynamic>;
    final user = await _userService.register(
      email:    body['email'] as String,
      password: body['password'] as String,
      name:     body['name'] as String,
    );
    return Response(201,
        body: jsonEncode(user.toJson()),
        headers: {'Content-Type': 'application/json'});
  }

  Future<Response> _getAll(Request request) async {
    final page  = int.tryParse(request.url.queryParameters['page']  ?? '1') ?? 1;
    final limit = int.tryParse(request.url.queryParameters['limit'] ?? '20') ?? 20;
    final users = await _userService.getAll(page: page, limit: limit);
    return Response.ok(
      jsonEncode({'users': users.map((u) => u.toJson()).toList(),
                  'meta':  {'page': page, 'limit': limit}}),
      headers: {'Content-Type': 'application/json'},
    );
  }

  Future<Response> _getById(Request request, String id) async {
    final user = await _userService.getById(id);
    return Response.ok(jsonEncode(user.toJson()),
        headers: {'Content-Type': 'application/json'});
  }

  Future<Response> _delete(Request request, String id) async {
    await _userService.delete(id);
    return Response(204);
  }
}

// Logging middleware
Middleware loggingMiddleware() {
  return (Handler inner) {
    return (Request request) async {
      final sw = Stopwatch()..start();
      final response = await inner(request);
      print('[${DateTime.now()}] ${request.method} '
            '${request.requestedUri} ${response.statusCode} '
            '${sw.elapsedMilliseconds}ms');
      return response;
    };
  };
}

// Error-handling middleware
Middleware handleErrors() {
  return (Handler inner) {
    return (Request request) async {
      try {
        return await inner(request);
      } on NotFoundException catch (e) {
        return _jsonError(404, e.message);
      } on ValidationException catch (e) {
        return _jsonError(422, e.message, errors: e.errors);
      } on UnauthorizedException {
        return _jsonError(401, 'Unauthorized');
      } catch (e, stack) {
        print('Unhandled: $e\n$stack');
        return _jsonError(500, 'Internal server error');
      }
    };
  };
}

Response _jsonError(int status, String message,
    {Map<String, dynamic>? errors}) {
  return Response(
    status,
    body: jsonEncode({'error': message, if (errors != null) 'errors': errors}),
    headers: {'Content-Type': 'application/json'},
  );
}

class UnauthorizedException implements Exception {
  final String message;
  UnauthorizedException([this.message = 'Unauthorized']);
}

class NotFoundException implements Exception {
  final String message;
  NotFoundException(this.message);
}

class ValidationException implements Exception {
  final String message;
  final Map<String, List<String>> errors;
  ValidationException(this.message, [this.errors = const {}]);
}

// test/handlers/users_handler_test.dart
import 'package:shelf/shelf.dart';
import 'package:test/test.dart';
import 'package:mocktail/mocktail.dart';

class MockUserService extends Mock implements UserService {}

void main() {
  late MockUserService mockService;
  late UsersHandler handler;

  setUp(() {
    mockService = MockUserService();
    handler     = UsersHandler(mockService);
  });

  test('GET / returns 200 with users', () async {
    when(() => mockService.getAll(page: any(named: 'page'),
                                  limit: any(named: 'limit')))
        .thenAnswer((_) async => []);

    final request  = Request('GET', Uri.parse('http://localhost/'));
    final response = await handler.router.call(request);

    expect(response.statusCode, 200);
  });
}
